INSERT INTO `standard_clause` (`id`, `standard_id`, `stage`, `clause_code`, `clause_name`, `requirement`, `check_rule_json`) VALUES
  (1, 1, 'PLANTING', 'PLT-01', '土壤墒情管理 #1', '土壤含水量保持在适宜范围，定期进行墒情监测。', '{"type": "SELECT", "threshold": "合格", "unit": "mg/kg"}'),
  (2, 1, 'PLANTING', 'PLT-02', '种子质量要求 #2', '使用经检疫合格、发芽率达到标准的优质种子。', '{"type": "SELECT", "threshold": "≥80", "unit": "分"}'),
  (3, 1, 'PROCESSING', 'PRC-03', '收割作业规范 #3', '采用机械化收割，控制留茬高度，减少谷粒损失。', '{"type": "BOOLEAN", "threshold": "≤0.05", "unit": "分"}'),
  (4, 1, 'PROCESSING', 'PRC-04', '烘干工艺控制 #4', '稻谷烘干温度控制在40℃以下，水分降至14.5%以下。', '{"type": "BOOLEAN", "threshold": "≤0.05", "unit": "分"}'),
  (5, 1, 'QUALITY', 'QLT-05', '农药残留检测 #5', '每批次产品农药残留指标须符合国家绿色食品标准。', '{"type": "SELECT", "threshold": "合格", "unit": "分"}'),
  (6, 1, 'QUALITY', 'QLT-06', '重金属检测 #6', '镉、铅、砷等重金属含量不得超过国家标准限值。', '{"type": "BOOLEAN", "threshold": "≤0.05", "unit": "-"}'),
  (7, 1, 'GRADING', 'GRD-07', '外观分级 #7', '按米粒完整度、垩白度、色泽等指标进行特级/一级/二级分级。', '{"type": "NUMERIC", "threshold": "≤0.05", "unit": "分"}'),
  (8, 1, 'GRADING', 'GRD-08', '食味品质 #8', '食味值不低于80分，直链淀粉含量符合优质丝苗米范围。', '{"type": "SELECT", "threshold": "≥80", "unit": "mg/kg"}'),
  (9, 1, 'PACKAGING', 'PKG-09', '包装标识 #9', '包装须标明产地、等级、净含量、生产日期、执行标准。', '{"type": "NUMERIC", "threshold": "≤0.05", "unit": "mg/kg"}'),
  (10, 1, 'DISTRIBUTION', 'DIS-10', '冷链储运 #10', '运输过程保持干燥通风，防止霉变和交叉污染。', '{"type": "NUMERIC", "threshold": "合格", "unit": "-"}'),
